</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <queue>
#include <vector>
#include <cstring>
#include <climits>
#include <algorithm>
#include <string>
using namespace std;

int N, LIMIT;
vector<string> G1, G2;
int D1[30][30], D2[30][30];
const int DX[4] = {0, 0, -1, 1};
const int DY[4] = {1, -1, 0, 0};

struct Edge {
    int src, dst, cap, flow;
    Edge(int s, int d, int c) : src(s), dst(d), cap(c), flow(0) {}
};

vector<Edge> E;
vector<int> adj[2000];
int lvl[2000], pr[2000];

bool inRange(int x, int y) { return x >= 0 && x < N && y >= 0 && y < N; }

void bfs1(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j) D1[i][j] = INT_MAX;
    queue<pair<int, int>> q;
    q.push({sx, sy});
    D1[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + DX[k], ny = y + DY[k];
            if (inRange(nx, ny) && D1[nx][ny] == INT_MAX && G2[nx][ny] != 'Y') {
                D1[nx][ny] = D1[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void bfs2(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j) D2[i][j] = INT_MAX;
    queue<pair<int, int>> q;
    q.push({sx, sy});
    D2[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (D2[x][y] >= D1[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + DX[k], ny = y + DY[k];
            if (inRange(nx, ny) && D2[nx][ny] == INT_MAX && G1[nx][ny] != 'Y' && D2[x][y] + 1 <= D1[nx][ny]) {
                D2[nx][ny] = D2[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

bool bfs() {
    memset(lvl, -1, sizeof(lvl));
    queue<int> q;
    q.push(0);
    lvl[0] = 0;
    while (!q.empty() && lvl[N*N*2+1] == -1) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            auto &e = E[id];
            if (lvl[e.dst] == -1 && e.flow < e.cap) {
                lvl[e.dst] = lvl[u] + 1;
                q.push(e.dst);
            }
        }
    }
    return lvl[N*N*2+1] != -1;
}

int dfs(int u, int f) {
    if (!f || u == N*N*2+1) return f;
    for (int &i = pr[u]; i < (int)adj[u].size(); ++i) {
        int id = adj[u][i];
        auto &e = E[id];
        if (lvl[e.dst] != lvl[u] + 1) continue;
        int sent = dfs(e.dst, min(f, e.cap - e.flow));
        if (sent) {
            e.flow += sent;
            E[id^1].flow -= sent;
            return sent;
        }
    }
    return 0;
}

int flow() {
    int result = 0;
    while (bfs()) {
        memset(pr, 0, sizeof(pr));
        while (int sent = dfs(0, INT_MAX)) result += sent;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> LIMIT;
    G1.resize(N); G2.resize(N);
    for (int i = 0; i < N; ++i) cin >> G1[i];
    for (int i = 0; i < N; ++i) cin >> G2[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (G2[i][j] == 'Z') {
                G1[i][j] = G2[i][j] = 'Y';
                zx = i; zy = j;
            }
        }
    }

    bfs1(zx, zy);

    int V = 2 * N * N + 2;
    for (int i = 0; i < V; ++i) adj[i].clear();
    E.clear();

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (G1[i][j] == 'Y') continue;
            int u = i * N + j + 1;
            int v = N * N + u;
            int c1 = G1[i][j] - '0';
            int c2 = G2[i][j] - '0';

            E.emplace_back(0, u, c1); adj[0].push_back(E.size() - 1);
            E.emplace_back(u, 0, 0); adj[u].push_back(E.size() - 1);
            E.emplace_back(v, V-1, c2); adj[v].push_back(E.size() - 1);
            E.emplace_back(V-1, v, 0); adj[V-1].push_back(E.size() - 1);

            bfs2(i, j);
            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (G2[x][y] == 'Y' || D2[x][y] > LIMIT) continue;
                    int w = N * N + x * N + y + 1;
                    E.emplace_back(u, w, c1); adj[u].push_back(E.size() - 1);
                    E.emplace_back(w, u, 0); adj[w].push_back(E.size() - 1);
                }
            }
        }
    }

    cout << flow() << '\n';
    return 0;
}
